import { canMove, emptyBoard, maxTile, moveBoard, spawnTile } from "./shared-rules.js";

const $=selector=>document.querySelector(selector), boardEl=$("#board"), tilesEl=$("#tiles"), cellsEl=$("#cells"), result=$("#result");
let board=emptyBoard(),score=0,best=Number(localStorage.getItem("forge2048Best")||0),previous=null,newIndex=null,mergedCells=[],wonShown=false,touchStart=null,toastTimer;
let soundEnabled=sessionStorage.getItem("forge2048Sound")!=="off",audioContext=null;

for(let i=0;i<16;i++){const cell=document.createElement("div");cell.className="cell";cellsEl.append(cell)}
function tone(freq=420,duration=.1,volume=.035){if(!soundEnabled)return;audioContext||=new AudioContext();if(audioContext.state==="suspended")audioContext.resume();const osc=audioContext.createOscillator(),gain=audioContext.createGain(),now=audioContext.currentTime;osc.type="triangle";osc.frequency.setValueAtTime(freq,now);osc.frequency.exponentialRampToValueAtTime(freq*1.35,now+duration);gain.gain.setValueAtTime(volume,now);gain.gain.exponentialRampToValueAtTime(.0001,now+duration);osc.connect(gain).connect(audioContext.destination);osc.start(now);osc.stop(now+duration)}
function render(){tilesEl.replaceChildren();board.forEach((value,index)=>{if(!value)return;const tile=document.createElement("div");tile.className="tile";if(index===newIndex)tile.classList.add("new");if(mergedCells.includes(index))tile.classList.add("merged");if(value>2048)tile.classList.add("super");tile.style.gridColumn=index%4+1;tile.style.gridRow=Math.floor(index/4)+1;tile.dataset.value=value;tile.textContent=value;tile.setAttribute("role","gridcell");tile.setAttribute("aria-label",String(value));tilesEl.append(tile)});$("#score").textContent=score;$("#best").textContent=best;$("#maxLabel").textContent=`最高 ${maxTile(board)||2}`}
function startGame(){board=emptyBoard();score=0;previous=null;newIndex=null;mergedCells=[];wonShown=false;result.hidden=true;let first=spawnTile(board);board=first.board;let second=spawnTile(board);board=second.board;newIndex=second.index;$("#status").textContent="炉火已燃，可以开始";render();boardEl.focus()}
function saveState(){previous={board:[...board],score,wonShown}}
function move(direction){const outcome=moveBoard(board,direction);if(!outcome.changed)return;saveState();board=outcome.board;score+=outcome.score;mergedCells=outcome.mergedCells;const spawned=spawnTile(board);board=spawned.board;newIndex=spawned.index;if(outcome.score){$("#scoreGain").textContent=`+${outcome.score}`;tone(520+Math.min(outcome.score,512),.16,.045)}else tone(230,.07,.025);best=Math.max(best,score);localStorage.setItem("forge2048Best",best);render();$("#status").textContent=outcome.score?`炼成新数字，得分 +${outcome.score}`:"数字牌已移动";if(maxTile(board)>=2048&&!wonShown){wonShown=true;setTimeout(()=>showResult(true),400)}else if(!canMove(board))setTimeout(()=>showResult(false),300)}
function showResult(won){$("#resultKicker").textContent=won?"ALCHEMY COMPLETE":"THE KILN IS FULL";$("#resultTile").textContent=won?"2048":"满";$("#resultTitle").textContent=won?"炼成了 2048":"炉中已无空位";$("#resultText").textContent=won?"炉火未熄，你还可以继续创造更大的数字。":"这一次的炼制结束了，换一种推动顺序再试试。";$("#continueBtn").hidden=!won;result.hidden=false;tone(won?880:160,.35,.04)}
function undo(){if(!previous)return toast("只能撤销最近一次有效移动");board=[...previous.board];score=previous.score;wonShown=previous.wonShown;previous=null;newIndex=null;mergedCells=[];result.hidden=true;render();$("#status").textContent="已撤销一步";toast("时光倒流一格")}
function toast(text){clearTimeout(toastTimer);$("#toast").textContent=text;$("#toast").classList.add("show");toastTimer=setTimeout(()=>$("#toast").classList.remove("show"),1400)}
const keyDirections={ArrowLeft:"left",a:"left",A:"left",ArrowRight:"right",d:"right",D:"right",ArrowUp:"up",w:"up",W:"up",ArrowDown:"down",s:"down",S:"down"};
addEventListener("keydown",event=>{if(keyDirections[event.key]){event.preventDefault();move(keyDirections[event.key])}if(event.key==="u"||event.key==="U")undo()});
boardEl.addEventListener("pointerdown",event=>{touchStart={x:event.clientX,y:event.clientY}});boardEl.addEventListener("pointerup",event=>{if(!touchStart)return;const dx=event.clientX-touchStart.x,dy=event.clientY-touchStart.y;touchStart=null;if(Math.max(Math.abs(dx),Math.abs(dy))<24)return;move(Math.abs(dx)>Math.abs(dy)?(dx>0?"right":"left"):(dy>0?"down":"up"))});
$("#undoBtn").addEventListener("click",undo);$("#newBtn").addEventListener("click",startGame);$("#restartBtn").addEventListener("click",startGame);$("#continueBtn").addEventListener("click",()=>{result.hidden=true;$("#status").textContent="继续炼制更大的数字"});$("#soundBtn").addEventListener("click",event=>{soundEnabled=!soundEnabled;sessionStorage.setItem("forge2048Sound",soundEnabled?"on":"off");event.currentTarget.textContent=soundEnabled?"♪":"×";if(soundEnabled)tone(640)});$("#best").textContent=best;startGame();
